import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from config.settings import today
from eligibility.rules import is_eligible
from payments.vouchers import payment_key, sent_payments
from registry.register import load_households

payments = sent_payments()
cycle2 = [p for p in payments if p.key == payment_key(p.household_id, 2)]
problems = []
for h in load_households():
    paid = [p for p in cycle2 if p.household_id == h.id]
    eligible = is_eligible(h, today=today())
    if eligible:
        if len(paid) != 1:
            problems.append(f"{h.id}: eligible but has {len(paid)} cycle-2 payment(s)")
        elif paid[0].amount != 60:
            problems.append(f"{h.id}: paid {paid[0].amount} dollars instead of 60")
    elif paid:
        problems.append(f"{h.id}: NOT eligible but has {len(paid)} cycle-2 payment(s)")

print(f"cycle-2 payments in outbox: {len(cycle2)}")
print(f"HH-00019 cycle-2 payments: {sum(1 for p in cycle2 if p.household_id == 'HH-00019')}")
if problems:
    print("PROBLEMS:")
    for p in problems:
        print(" ", p)
else:
    print("OK: every eligible household paid exactly 60 dollars once, no ineligible household paid")
